 import axios from 'axios'

// SportScore - Free API (no key required)
const BASE_URL = 'https://sportscore.com/api/v1'

export async function getLiveMatches() {
    try {
        const response = await axios.get(`${BASE_URL}/football/matches/live`)
        return response.data
    } catch (error) {
        console.error('Live matches error:', error)
        return []
    }
}

export async function getStandings(league) {
    try {
        const response = await axios.get(`${BASE_URL}/football/standings/${league}`)
        return response.data
    } catch (error) {
        console.error('Standings error:', error)
        return []
    }
}

export async function getTodaysMatches() {
    try {
        const today = new Date().toISOString().split('T')[0]
        const response = await axios.get(`${BASE_URL}/football/matches/date/${today}`)
        return response.data
    } catch (error) {
        console.error('Matches error:', error)
        return []
    }
}
